import unittest
from decimal import Decimal

from tiers import discount_for, next_tier, order_total, validate_scale


class ValidateScaleTests(unittest.TestCase):
    def test_sorts_by_threshold_and_returns_tuples(self):
        result = validate_scale([(500, 10), (100, 5)])
        self.assertEqual(result, [(100, 5), (500, 10)])
        self.assertIsInstance(result[0], tuple)

    def test_empty_scale_allowed(self):
        self.assertEqual(validate_scale([]), [])

    def test_does_not_mutate_argument(self):
        scale = [(500, 10), (100, 5)]
        validate_scale(scale)
        self.assertEqual(scale, [(500, 10), (100, 5)])

    def test_rejects_bad_threshold(self):
        for bad in [(0, 5), (-1, 5)]:
            with self.assertRaises(ValueError):
                validate_scale([bad])

    def test_rejects_bad_percent(self):
        for bad in [(-1,), (100,)]:
            with self.assertRaises(ValueError):
                validate_scale([(100, bad[0])])

    def test_rejects_duplicate_thresholds(self):
        with self.assertRaises(ValueError):
            validate_scale([(100, 5), (100, 5)])

    def test_rejects_decreasing_percent(self):
        with self.assertRaises(ValueError):
            validate_scale([(100, 10), (500, 5)])

    def test_equal_percent_allowed(self):
        self.assertEqual(validate_scale([(100, 5), (500, 5)]), [(100, 5), (500, 5)])


class DiscountForTests(unittest.TestCase):
    def test_threshold_inclusive(self):
        self.assertEqual(discount_for(100, [(100, 5)]), 5)
        self.assertEqual(discount_for(99, [(100, 5)]), 0)

    def test_below_all_and_empty(self):
        self.assertEqual(discount_for(0, [(100, 5)]), 0)
        self.assertEqual(discount_for(50, []), 0)

    def test_highest_reached_step(self):
        scale = [(100, 5), (500, 10), (1000, 15)]
        self.assertEqual(discount_for(999, scale), 10)
        self.assertEqual(discount_for(1000, scale), 15)

    def test_negative_qty_raises(self):
        with self.assertRaises(ValueError):
            discount_for(-1, [(100, 5)])


class OrderTotalTests(unittest.TestCase):
    def test_discount_applies_to_whole_sum(self):
        self.assertEqual(order_total(200, "10.00", [(100, 5)]), Decimal("1900.00"))

    def test_rounds_half_up_once(self):
        # 3 * 0.01 = 0.03, скидка 50% -> 0.015 -> 0.02
        self.assertEqual(order_total(3, "0.01", [(1, 50)]), Decimal("0.02"))

    def test_accepts_decimal_price(self):
        self.assertEqual(order_total(2, Decimal("1.50"), []), Decimal("3.00"))


class NextTierTests(unittest.TestCase):
    def test_returns_next_threshold_and_gap(self):
        self.assertEqual(next_tier(50, [(100, 5), (500, 10)]), (100, 50))

    def test_skips_reached_steps(self):
        self.assertEqual(next_tier(100, [(100, 5), (500, 10)]), (500, 400))

    def test_none_at_top_or_empty(self):
        self.assertIsNone(next_tier(500, [(100, 5), (500, 10)]))
        self.assertIsNone(next_tier(0, []))

    def test_negative_qty_raises(self):
        with self.assertRaises(ValueError):
            next_tier(-1, [(100, 5)])


if __name__ == "__main__":
    unittest.main()
