```python
import unittest
from decimal import Decimal

from tiers import discount_for, next_tier, order_total, validate_scale


def test_validate_scale_unsorted_duplicates_detected():
    with unittest.TestCase().assertRaises(ValueError):
        validate_scale([(500, 10), (100, 5), (500, 10)])


def test_validate_scale_unsorted_decreasing_detected():
    with unittest.TestCase().assertRaises(ValueError):
        validate_scale([(1000, 5), (100, 10)])


def test_validate_scale_returns_new_list_not_same_object():
    scale = [(100, 5)]
    result = validate_scale(scale)
    assert result is not scale
    assert result == [(100, 5)]


def test_validate_scale_accepts_zero_percent():
    assert validate_scale([(100, 0)]) == [(100, 0)]


def test_validate_scale_accepts_99_percent():
    assert validate_scale([(100, 99)]) == [(100, 99)]


def test_discount_for_unsorted_scale():
    assert discount_for(600, [(1000, 15), (100, 5), (500, 10)]) == 10


def test_discount_for_does_not_mutate_scale():
    scale = [(500, 10), (100, 5)]
    discount_for(600, scale)
    assert scale == [(500, 10), (100, 5)]


def test_discount_for_zero_percent_step():
    assert discount_for(100, [(100, 0)]) == 0


def test_order_total_zero_qty():
    assert order_total(0, "10.00", [(100, 5)]) == Decimal("0.00")


def test_order_total_no_discount_below_threshold():
    assert order_total(50, "2.00", [(100, 5)]) == Decimal("100.00")


def test_order_total_rounds_half_up_second_case():
    # 1 * 0.05 = 0.05, скидка 10% -> 0.045 -> 0.05
    assert order_total(1, "0.05", [(1, 10)]) == Decimal("0.05")


def test_order_total_does_not_mutate_scale():
    scale = [(500, 10), (100, 5)]
    order_total(600, "1.00", scale)
    assert scale == [(500, 10), (100, 5)]


def test_next_tier_unsorted_scale():
    assert next_tier(50, [(500, 10), (100, 5)]) == (100, 50)


def test_next_tier_does_not_mutate_scale():
    scale = [(500, 10), (100, 5)]
    next_tier(50, scale)
    assert scale == [(500, 10), (100, 5)]


def test_next_tier_above_top_returns_none():
    assert next_tier(1000, [(100, 5), (500, 10)]) is None


def test_next_tier_zero_with_scale():
    assert next_tier(0, [(100, 5)]) == (100, 100)
